    const O = S.clone().addScaledVector(w, -Lb * Math.sqrt(3) / 2); // far coincident corner
    const A = O.clone().addScaledVector(E[0], Lb), B = A.clone().addScaledVector(E[1], Lb), O2 = B.clone().addScaledVector(E[2], Lb);
    const hs = (X) => (w0 / 2) * X.distanceTo(Vp) / dref;
    const tri = new GB();
