    const lp = new THREE.Mesh(new THREE.PlaneGeometry(3.6, 2.2), panelMat); lp.rotation.x = Math.PI / 2; lp.position.set((bx0 + bx1) / 2, bh - 0.02, (bz0 + bz1) / 2); D.add(lp);
    const tints = [[0xffffff, 'Neutral white light'], [0xffb060, 'Warm amber light'], [0x7fa8ff, 'Cool blue light'], [0x9fff9f, 'Green light']]; let ti = 0;
