    const sp = new THREE.Mesh(new THREE.PlaneGeometry(1.2, 1.8), U.track(new THREE.MeshStandardMaterial({ map: sdtTex, roughness: 0.8 }))); sp.position.set(17.74, 1.9, 13.5); sp.rotation.y = -Math.PI / 2; D.add(sp);
